<?php
declare(strict_types=1);
function operations_post(string $path,array $u): never {
 if($path==='/admin/roles'){
 $key=strtolower(text_input('role_key',50));if(!preg_match('/^[a-z][a-z0-9_]{2,49}$/',$key))throw new InvalidArgumentException('Use a role key with 3–50 lowercase letters, numbers or underscores.');if($key==='admin')throw new InvalidArgumentException('The administrator role is protected.');$name=text_input('role_name',100);$description=text_input('description',2000);$permissions=array_values(array_unique(array_filter((array)($_POST['permissions']??[]),'is_string')));foreach($permissions as $p)if(!isset(permission_catalogue()[$p]))throw new InvalidArgumentException('Unknown permission.');
 if($key==='citizen'){$allowed=['requests.create','requests.scope_own','requests.message','requests.withdraw','requests.reopen','requests.feedback','documents.download','documents.print'];if(array_diff($permissions,$allowed))throw new InvalidArgumentException('Public citizen accounts cannot be granted staff privileges.');if(!in_array('requests.scope_own',$permissions,true))throw new InvalidArgumentException('Citizens must retain access to their own requests.');}
 elseif(in_array('requests.create',$permissions,true)||in_array('requests.scope_own',$permissions,true))throw new InvalidArgumentException('Own-request creation belongs to the citizen role. Staff roles use department or organisation access.');
 if(in_array('requests.reroute',$permissions,true)&&!in_array('requests.scope_all',$permissions,true))throw new InvalidArgumentException('Cross-department routing requires organisation-wide request access.');
 $active=isset($_POST['active'])?1:0;if($key==='citizen'&&!$active)throw new InvalidArgumentException('The public citizen role must remain active.');
 db()->beginTransaction();try{$existing=row('SELECT * FROM roles WHERE role_key=?',[$key]);if($existing)sql('UPDATE roles SET role_name=?,description=?,active=? WHERE role_key=?',[$name,$description,$active,$key]);else insert('roles',['role_key'=>$key,'role_name'=>$name,'description'=>$description,'active'=>$active,'is_system'=>0]);sql('DELETE FROM role_permissions WHERE role_key=?',[$key]);foreach($permissions as $p)insert('role_permissions',['role_key'=>$key,'permission_key'=>$p]);sql('UPDATE users SET auth_version=auth_version+1 WHERE role=? OR id IN (SELECT user_id FROM user_roles WHERE role_key=?)',[$key,$key]);audit('role.permissions_changed',null,['role'=>$key,'permissions'=>$permissions,'active'=>$active]);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash('Role and permissions saved. Affected users must sign in again.');go('admin/roles?edit='.rawurlencode($key));
 }
 if($path==='/admin/templates'){
 $key=strtolower(text_input('template_key',60));if(!preg_match('/^[a-z][a-z0-9_]{2,59}$/',$key))throw new InvalidArgumentException('Use a template key containing letters, numbers and underscores.');$name=text_input('name',140);$subject=text_input('subject',180);$html=clean_email_html(text_input('html_body',30000));$plain=text_input('plain_body',12000);$active=isset($_POST['active'])?1:0;
 $existing=row('SELECT * FROM email_templates WHERE template_key=?',[$key]);if($existing)sql('UPDATE email_templates SET name=?,subject=?,html_body=?,plain_body=?,active=?,updated_at=? WHERE template_key=?',[$name,$subject,$html,$plain,$active,now(),$key]);else insert('email_templates',['template_key'=>$key,'name'=>$name,'subject'=>$subject,'html_body'=>$html,'plain_body'=>$plain,'active'=>$active,'updated_at'=>now()]);audit('email_template.saved',null,['template'=>$key]);flash('Template saved. Future notifications use the updated version; existing outbox records retain their original message.');go('admin/templates?edit='.rawurlencode($key));
 }
 if($path==='/admin/compose'){
 $uid=(int)($_POST['recipient_id']??0);$recipient=row("SELECT * FROM users WHERE id=? AND status='active'",[$uid]);if(!$recipient)throw new InvalidArgumentException('Choose an active registered recipient.');$title=text_input('title',180);$message=text_input('message',8000);$key=text_input('template_key',60);$tpl=row('SELECT * FROM email_templates WHERE template_key=? AND active=1',[$key]);if(!$tpl)throw new InvalidArgumentException('Choose an active template.');$channel=text_input('channel',20);if(!in_array($channel,['in_app','email','sms'],true))throw new InvalidArgumentException('Choose a supported channel.');if($channel==='email'&&!$recipient['notify_email'])throw new InvalidArgumentException('This recipient has opted out of routine email updates.');if($channel==='sms'&&(!$recipient['notify_sms']||!$recipient['phone']))throw new InvalidArgumentException('This recipient has not opted into SMS or has no phone number.');
 $render=template_render($tpl,['name'=>$recipient['name'],'title'=>$title,'message'=>$message,'link'=>url('notifications'),'app_name'=>setting('app_name','CivicFlow')]);db()->beginTransaction();try{notify($uid,$title,$message,'notifications',null,false);if($channel!=='in_app')insert('outbox',['user_id'=>$uid,'channel'=>$channel,'recipient'=>$recipient[$channel==='email'?'email':'phone'],'subject'=>$render['subject'],'body'=>$render['body'],'html_body'=>$channel==='email'?$render['html_body']:null,'template_key'=>$key,'state'=>setting($channel.'_enabled','0')==='1'?'pending':'configuration_required','created_at'=>now()]);audit('communication.composed',$uid,['channel'=>$channel,'template'=>$key]);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash($channel==='in_app'?'In-app notice created.':'Message queued. Delivery is processed through the outbox.');go('admin/compose');
 }
 if($path==='/admin/outbox/cancel'){
 $id=(int)($_POST['id']??0);$q=sql("UPDATE outbox SET state='cancelled',next_attempt_at=NULL WHERE id=? AND state IN ('pending','retry','configuration_required','failed')",[$id]);if(!$q->rowCount())throw new InvalidArgumentException('This message cannot be cancelled. It may already be processing or sent.');audit('notification.cancelled',$id);flash('Queued delivery cancelled.');go('admin/outbox');
 }
 abort_page(404,'Operation not found.');
}
